```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract SafeGalaxyCoin is ERC20, Ownable {
    uint256 private constant LOCK_DURATION = 365 days; // 1 year
    uint256 private constant LIQUIDITY_POOL_THRESHOLD = 1e6 ether; // 1 million ETH

    constructor() ERC20("SafeGalaxyCoin", "SGC") {
        _mint(msg.sender, 1000000 * 10**decimals()); // Mint 1 million SGC tokens
    }

    modifier onlyAfterLock() {
        require(block.timestamp >= block.timestamp + LOCK_DURATION, "Liquidity lock is still active");
        _;
    }

    function emergencyWithdraw() external onlyOwner {
        require(address(this).balance >= LIQUIDITY_POOL_THRESHOLD, "Liquidity pool threshold not met");
        payable(owner()).transfer(address(this).balance);
    }

    function _beforeTokenTransfer(address from, address to, uint256 amount) internal override(ERC20) onlyAfterLock {
        super._beforeTokenTransfer(from, to, amount);
    }

    function addLiquidity(uint256 amount) external payable onlyOwner {
        require(amount > 0, "Amount must be greater than zero");
        _mint(msg.sender, amount * 10**decimals());
    }
}
```

